import { useState } from "react";

const qaData = [
  {
    id: "QA-01", cat: "Model Health", gisd: false,
    name: "Room Area vs Program SF",
    emoji: "📐",
    kidVersion: "Like checking your bedroom is the right size before moving in. Every room in Revit gets compared to the GISD program sheet. Too big or too small? It gets flagged.",
    tool: "Room Schedule + Area formula",
    milestone: "SD / DD / CD",
    dynamo: true,
    tdg: "Pfluger A2"
  },
  {
    id: "QA-02", cat: "Model Health", gisd: false,
    name: "Room Number Sequence",
    emoji: "🔢",
    kidVersion: "Like making sure no two kids share a locker number. Revit's built-in warning finder catches any room numbers used twice.",
    tool: "Review > Warnings > Duplicate Values",
    milestone: "DD / CD",
    dynamo: false,
    tdg: "Pfluger A2"
  },
  {
    id: "QA-03", cat: "Drawing Production", gisd: false,
    name: "Wall Type Tags Complete",
    emoji: "🏷️",
    kidVersion: "Every wall needs a label so the builder knows what it's made of — like name-tags at a party so nobody's confused.",
    tool: "Tag All > Wall Tags",
    milestone: "CD",
    dynamo: true,
    tdg: "Pfluger A2"
  },
  {
    id: "QA-04", cat: "Drawing Production", gisd: false,
    name: "Door Tags Complete",
    emoji: "🚪",
    kidVersion: "Every door gets a number that matches its room. So door 101 goes to room 101. Tag All does this in one click.",
    tool: "Tag All > Door Tags",
    milestone: "CD",
    dynamo: true,
    tdg: "Pfluger A2"
  },
  {
    id: "QA-05", cat: "Drawing Production", gisd: false,
    name: "Unplaced Views Check",
    emoji: "🗂️",
    kidVersion: "Finds drawings hiding in the model that never made it onto a sheet — like homework stuffed in a backpack, never turned in.",
    tool: "View > Manage Views",
    milestone: "CD",
    dynamo: false,
    tdg: "Pfluger G0"
  },
  {
    id: "QA-06", cat: "Model Health", gisd: false,
    name: "Warnings Report Clean",
    emoji: "⚠️",
    kidVersion: "Revit's own warning list — like a spell-checker but for buildings. Fix all 'room not enclosed' and 'duplicate element' warnings before submittal.",
    tool: "Manage > Review Warnings",
    milestone: "DD / CD",
    dynamo: false,
    tdg: "All Series"
  },
  {
    id: "QA-07", cat: "GISD Technology", gisd: true,
    name: "★ MDF/IDF Room Size Check",
    emoji: "🖥️",
    kidVersion: "Checks MDF is ≥150 SF and each IDF is ≥120 SF. Like making sure the server room is big enough for all the computers — GISD requires exact minimums!",
    tool: "Room Schedule → filter GISD_TelecomRoom_Type",
    milestone: "DD / CD",
    dynamo: true,
    tdg: "GISD TDG Div 27 §7.01"
  },
  {
    id: "QA-08", cat: "GISD Security", gisd: true,
    name: "★ Card Reader Door Flag",
    emoji: "💳",
    kidVersion: "Finds every door needing a card reader and confirms it's on the Security plan. Like a guest list at the front door — nobody gets in without being on the list. Must be on RIGHT side of frame!",
    tool: "Door Schedule → GISD_CardReader_Required = Yes",
    milestone: "DD / CD",
    dynamo: true,
    tdg: "GISD TDG Div 28 / Card Reader Email 1/16/26"
  },
  {
    id: "QA-09", cat: "GISD Conveying", gisd: true,
    name: "★ Elevator Type = Hydraulic",
    emoji: "🛗",
    kidVersion: "Checks the elevator parameter says 'Hydraulic'. GISD Maintenance asked for hydraulic-only (email Jan 30, 2026). No traction elevators!",
    tool: "Specialty Equipment Schedule → GISD_Elevator_Type",
    milestone: "DD / CD",
    dynamo: false,
    tdg: "GISD TDG Div 14 / Elevator Email 1/30/26"
  },
  {
    id: "QA-10", cat: "GISD Conveying", gisd: true,
    name: "★ Elevator Door Clear ≥ 42\"",
    emoji: "↔️",
    kidVersion: "Measures the elevator door opening — at least 3½ feet wide so wheelchairs, book carts, and cleaning equipment can get in without turning.",
    tool: "Door Schedule in elevator lobby",
    milestone: "CD",
    dynamo: false,
    tdg: "GISD TDG Div 14 / TAS"
  },
  {
    id: "QA-11", cat: "GISD Plumbing", gisd: true,
    name: "★ Custodial Closet: Mop Sink + Floor Drain",
    emoji: "🧹",
    kidVersion: "Makes sure every janitor's closet has a mop sink and floor drain. Because mopping without a sink is a disaster — and GISD TDG requires it on every floor!",
    tool: "Room Schedule → GISD_Custodial_MopSink + FloorDrain",
    milestone: "DD / CD",
    dynamo: true,
    tdg: "GISD TDG Div 22"
  },
  {
    id: "QA-12", cat: "GISD Wellness", gisd: true,
    name: "★ Lactation Room Identified",
    emoji: "🤱",
    kidVersion: "Confirms at least one room is flagged as a private mothers/lactation room with a nearby sink. GISD regulation (effective 1/14/2020) requires this in all new buildings.",
    tool: "Room Schedule → GISD_LactationRoom = Yes",
    milestone: "DD / CD",
    dynamo: false,
    tdg: "GISD DG Regulation 2020"
  },
  {
    id: "QA-13", cat: "GISD Site", gisd: true,
    name: "★ Fencing Types Tagged on Site",
    emoji: "🏗️",
    kidVersion: "Every fence line on the site plan is labeled — Ornamental at the front entrance, Chain-Link at the perimeter. So the contractor builds the RIGHT fence in the RIGHT place.",
    tool: "Site model tags → GISD_Fence_Type annotation",
    milestone: "DD / CD",
    dynamo: true,
    tdg: "GISD TDG Div 32 / Fence Spec 2025"
  },
  {
    id: "QA-14", cat: "GISD Site", gisd: true,
    name: "★ Playground Use Zone Area",
    emoji: "🛝",
    kidVersion: "Checks that the fall zone (use zone) around playground equipment matches the Burke proposal. Like making sure there's enough space around the swings before a kid flies off.",
    tool: "Filled region / room boundary → GISD_Playground_UZArea",
    milestone: "DD / CD",
    dynamo: false,
    tdg: "ASTM F1487 / Burke Proposal"
  },
  {
    id: "QA-15", cat: "Drawing Production", gisd: false,
    name: "Sheet Index Complete",
    emoji: "📋",
    kidVersion: "Every sheet in the drawing list actually exists in the model. No phantom sheets, no surprise missing sheets at submittal time.",
    tool: "View > Sheet List Schedule",
    milestone: "CD",
    dynamo: false,
    tdg: "Pfluger G0"
  },
  {
    id: "QA-16", cat: "Drawing Production", gisd: false,
    name: "View Range / Crop Regions",
    emoji: "✂️",
    kidVersion: "Every drawing shows the right portion of the building — like making sure your photo isn't accidentally cropped to just show someone's foot.",
    tool: "Visual inspection of placed views",
    milestone: "CD",
    dynamo: false,
    tdg: "Pfluger All"
  },
  {
    id: "QA-17", cat: "Coordination", gisd: false,
    name: "MEP Linked Model Visible",
    emoji: "🔗",
    kidVersion: "Turns on the MEP (pipes, ducts, wires) Revit link in architectural views so you can spot conflicts — like checking your teammate's work before you both turn it in.",
    tool: "Visibility/Graphics > Revit Links",
    milestone: "CD",
    dynamo: false,
    tdg: "Pfluger A6/A7"
  },
  {
    id: "QA-18", cat: "Coordination", gisd: false,
    name: "Clash Detection (Interference Check)",
    emoji: "💥",
    kidVersion: "Runs Revit's built-in 'bump finder' between Structure and MEP. Catches things like a water pipe running straight through a steel beam before construction — way cheaper to fix on screen.",
    tool: "Collaborate > Interference Check",
    milestone: "CD",
    dynamo: false,
    tdg: "Pfluger A2"
  },
  {
    id: "QA-19", cat: "Model Health", gisd: false,
    name: "Workset Discipline Cleanup",
    emoji: "🗃️",
    kidVersion: "Every element is in the correct Workset (e.g. INT-FLOOR FINISHES, ARCH-WALLS) — like putting every toy back in the right box so the whole team can find things.",
    tool: "Manage > Worksets",
    milestone: "SD / DD / CD",
    dynamo: false,
    tdg: "Pfluger A9"
  },
  {
    id: "QA-20", cat: "GISD General", gisd: true,
    name: "★ All GISD Shared Parameters Filled",
    emoji: "📊",
    kidVersion: "Checks every GISD_ parameter (card reader location, fence type, telecom room SF, etc.) has a value — no blanks allowed before submittal. One Dynamo script can scan all of them at once.",
    tool: "Parameter Schedule → GISD_ params ≠ blank",
    milestone: "DD / CD",
    dynamo: true,
    tdg: "All GISD TDGs"
  }
];

const cats = ["All", "Model Health", "Drawing Production", "Coordination", "GISD Technology", "GISD Security", "GISD Conveying", "GISD Plumbing", "GISD Wellness", "GISD Site", "GISD General"];

const catColors = {
  "Model Health": "#1565C0",
  "Drawing Production": "#2E7D32",
  "Coordination": "#6A1B9A",
  "GISD Technology": "#7B2D8B",
  "GISD Security": "#B71C1C",
  "GISD Conveying": "#E65100",
  "GISD Plumbing": "#006064",
  "GISD Wellness": "#AD1457",
  "GISD Site": "#33691E",
  "GISD General": "#37474F",
};

export default function RevitQA() {
  const [filter, setFilter] = useState("All");
  const [expanded, setExpanded] = useState(null);
  const [showGisd, setShowGisd] = useState(false);

  const filtered = qaData.filter(q => {
    if (showGisd && !q.gisd) return false;
    if (filter === "All") return true;
    return q.cat === filter;
  });

  const gisdCount = qaData.filter(q => q.gisd).length;
  const dynamoCount = qaData.filter(q => q.dynamo).length;

  return (
    <div style={{
      minHeight: "100vh",
      background: "linear-gradient(135deg, #0D1B2A 0%, #1A2744 50%, #0D1B2A 100%)",
      fontFamily: "'Georgia', serif",
      color: "#E8EAF6",
      padding: "0 0 40px 0"
    }}>
      {/* Header */}
      <div style={{
        background: "linear-gradient(90deg, #0D1B2A 0%, #1565C0 50%, #0D1B2A 100%)",
        borderBottom: "3px solid #FFD54F",
        padding: "28px 32px 20px",
        position: "sticky", top: 0, zIndex: 100
      }}>
        <div style={{ maxWidth: 900, margin: "0 auto" }}>
          <div style={{ fontSize: 11, letterSpacing: 4, color: "#FFD54F", textTransform: "uppercase", marginBottom: 6 }}>
            Pfluger Architects · Garland ISD Elementary #4
          </div>
          <h1 style={{ margin: 0, fontSize: 22, fontWeight: "normal", color: "#FFFFFF", letterSpacing: 1 }}>
            Revit-Native QA Checklist System
          </h1>
          <div style={{ fontSize: 12, color: "#90CAF9", marginTop: 4 }}>
            Deliverable 02 · Explained simply · No external tools required · {qaData.length} checks total
          </div>

          {/* Stats row */}
          <div style={{ display: "flex", gap: 16, marginTop: 14, flexWrap: "wrap" }}>
            {[
              { label: "Total Checks", val: qaData.length, color: "#90CAF9" },
              { label: "★ GISD-Specific", val: gisdCount, color: "#FFD54F" },
              { label: "★DYNAMO Enabled", val: dynamoCount, color: "#A5D6A7" },
              { label: "Revit-Native", val: qaData.length - dynamoCount, color: "#CE93D8" },
            ].map(s => (
              <div key={s.label} style={{
                background: "rgba(255,255,255,0.07)",
                border: `1px solid ${s.color}44`,
                borderRadius: 8,
                padding: "8px 16px",
                textAlign: "center",
                minWidth: 100
              }}>
                <div style={{ fontSize: 22, fontWeight: "bold", color: s.color }}>{s.val}</div>
                <div style={{ fontSize: 10, color: "#B0BEC5", letterSpacing: 1 }}>{s.label}</div>
              </div>
            ))}
          </div>
        </div>
      </div>

      <div style={{ maxWidth: 900, margin: "0 auto", padding: "24px 16px 0" }}>
        {/* Filter bar */}
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginBottom: 20, alignItems: "center" }}>
          <div
            onClick={() => setShowGisd(!showGisd)}
            style={{
              cursor: "pointer",
              padding: "6px 14px",
              borderRadius: 20,
              fontSize: 11,
              fontFamily: "monospace",
              background: showGisd ? "#FFD54F" : "transparent",
              color: showGisd ? "#0D1B2A" : "#FFD54F",
              border: "1px solid #FFD54F",
              letterSpacing: 1,
              userSelect: "none"
            }}
          >
            ★ GISD ONLY
          </div>
          {cats.map(c => (
            <div
              key={c}
              onClick={() => setFilter(c)}
              style={{
                cursor: "pointer",
                padding: "6px 12px",
                borderRadius: 20,
                fontSize: 11,
                background: filter === c
                  ? (catColors[c] || "#1565C0")
                  : "rgba(255,255,255,0.05)",
                color: filter === c ? "#FFF" : "#90CAF9",
                border: `1px solid ${filter === c ? (catColors[c] || "#1565C0") : "#1E3A5F"}`,
                userSelect: "none",
                letterSpacing: 0.5
              }}
            >
              {c}
            </div>
          ))}
        </div>

        {/* Big concept box at top */}
        <div style={{
          background: "rgba(21, 101, 192, 0.15)",
          border: "1px solid #1565C0",
          borderLeft: "4px solid #FFD54F",
          borderRadius: 10,
          padding: "16px 20px",
          marginBottom: 24,
          fontSize: 13,
          lineHeight: 1.7,
          color: "#B3C5E8"
        }}>
          <span style={{ color: "#FFD54F", fontWeight: "bold" }}>What is a Revit-Native QA System?</span><br />
          Think of Revit like a giant LEGO set where every brick knows its name, size, and type. A QA system is like a checklist that Revit itself can check — using Schedules, Tags, Warnings, and Interference tools that are already inside Revit. No extra software. The checks marked <span style={{ color: "#A5D6A7" }}>★DYNAMO</span> can be automated with a Dynamo script (contact Pfluger DT). Checks marked <span style={{ color: "#FFD54F" }}>★ GISD</span> come directly from Garland ISD Technical Design Guidelines or owner emails.
        </div>

        {/* Cards */}
        <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
          {filtered.map((q) => {
            const isOpen = expanded === q.id;
            const catColor = catColors[q.cat] || "#37474F";
            return (
              <div
                key={q.id}
                onClick={() => setExpanded(isOpen ? null : q.id)}
                style={{
                  background: isOpen
                    ? "rgba(255,255,255,0.08)"
                    : "rgba(255,255,255,0.04)",
                  border: `1px solid ${isOpen ? catColor : "#1E3A5F"}`,
                  borderLeft: `4px solid ${catColor}`,
                  borderRadius: 10,
                  padding: isOpen ? "18px 20px 20px" : "14px 20px",
                  cursor: "pointer",
                  transition: "all 0.2s ease",
                }}
              >
                {/* Card header */}
                <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
                  <span style={{ fontSize: 22, flexShrink: 0 }}>{q.emoji}</span>
                  <div style={{ flex: 1 }}>
                    <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
                      <span style={{
                        fontFamily: "monospace", fontSize: 11,
                        color: "#78909C", letterSpacing: 1
                      }}>{q.id}</span>
                      {q.gisd && (
                        <span style={{
                          background: "#FFD54F22", border: "1px solid #FFD54F",
                          color: "#FFD54F", fontSize: 9, padding: "1px 7px",
                          borderRadius: 10, letterSpacing: 1
                        }}>★ GISD</span>
                      )}
                      {q.dynamo && (
                        <span style={{
                          background: "#A5D6A722", border: "1px solid #A5D6A7",
                          color: "#A5D6A7", fontSize: 9, padding: "1px 7px",
                          borderRadius: 10, letterSpacing: 1
                        }}>★DYNAMO</span>
                      )}
                      <span style={{
                        background: catColor + "33", border: `1px solid ${catColor}55`,
                        color: catColor === "#FFFFFF" ? "#000" : "#E0E0E0",
                        fontSize: 9, padding: "1px 7px", borderRadius: 10,
                        filter: "brightness(1.4)"
                      }}>{q.cat}</span>
                    </div>
                    <div style={{
                      fontSize: 14, color: "#E8EAF6", fontWeight: "normal",
                      marginTop: 3, letterSpacing: 0.3
                    }}>{q.name}</div>
                  </div>
                  <div style={{
                    fontSize: 18, color: "#546E7A", transform: isOpen ? "rotate(90deg)" : "none",
                    transition: "transform 0.2s", flexShrink: 0
                  }}>›</div>
                </div>

                {/* Expanded content */}
                {isOpen && (
                  <div style={{ marginTop: 16, paddingTop: 16, borderTop: "1px solid #1E3A5F" }}>
                    {/* Kid version */}
                    <div style={{
                      background: "rgba(255, 213, 79, 0.08)",
                      border: "1px solid #FFD54F44",
                      borderRadius: 8, padding: "12px 16px",
                      marginBottom: 14
                    }}>
                      <div style={{ fontSize: 10, color: "#FFD54F", letterSpacing: 2, marginBottom: 6 }}>
                        🧒 EXPLAINED LIKE YOU'RE 5
                      </div>
                      <div style={{ fontSize: 13, color: "#E0E0E0", lineHeight: 1.7 }}>
                        {q.kidVersion}
                      </div>
                    </div>

                    {/* Details grid */}
                    <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
                      {[
                        { label: "🔧 Revit Tool / Method", val: q.tool },
                        { label: "📅 When to Run", val: q.milestone },
                        { label: "🤖 Dynamo Automation", val: q.dynamo ? "Yes — contact Pfluger DT for script" : "Manual check in Revit" },
                        { label: "📄 Standard Reference", val: q.tdg },
                      ].map(d => (
                        <div key={d.label} style={{
                          background: "rgba(255,255,255,0.05)",
                          borderRadius: 6, padding: "10px 14px"
                        }}>
                          <div style={{ fontSize: 10, color: "#78909C", marginBottom: 4, letterSpacing: 0.5 }}>{d.label}</div>
                          <div style={{ fontSize: 12, color: "#B3C5E8", lineHeight: 1.5, fontFamily: d.label.includes("Tool") ? "monospace" : "inherit" }}>{d.val}</div>
                        </div>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            );
          })}
        </div>

        {filtered.length === 0 && (
          <div style={{ textAlign: "center", color: "#546E7A", padding: 40, fontSize: 14 }}>
            No checks match this filter. Try "All" or toggle GISD off.
          </div>
        )}

        {/* Footer */}
        <div style={{
          marginTop: 32, borderTop: "1px solid #1E3A5F",
          paddingTop: 20, fontSize: 11, color: "#546E7A", textAlign: "center", lineHeight: 1.8
        }}>
          Pfluger Architects · Garland Elementary #4 · Deliverable 02 – Revit-Native QA System<br />
          Aligned to: Pfluger Deliverables Standard V1.1 · Pfluger Documentation Guidelines V1.0 · GISD TDGs (April 2024) · GISD Structured Cabling Standards v2026.3.10
        </div>
      </div>
    </div>
  );
}
